{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Procainamide, a structurally close benzamide with a basic aminoethyl side chain, has an absolute oral bioavailability of 75% versus intravenous dosing in normal volunteers, supporting high F for the query's similar amide/morpholine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Trazodone, which contains a chlorophenyl and a piperazine/morpholine-like heterocycle, shows an absolute bioavailability of 65% in fed volunteers, directly supporting high oral bioavailability under the fed condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Isoniazid, a small polar amide/hydrazide, shows 78% oral bioavailability in fed patients, indicating that small amide-containing drugs can maintain high F in the fed state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Molsidomine, a morpholine-containing small molecule with notable first-pass metabolism, still has an absolute bioavailability of 44±15%, well above the 20% threshold, supporting high F for the query despite possible first-pass liability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved analogues with direct oral bioavailability measurements show F values well above 20% (44–93%), including fed-state data. The query's small amide/morpholine structure is most similar to procainamide and trazodone, both of which are highly bioavailable, so the prediction is high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule itself.",
    "Fed-state data are available only from analogues, not from the query under identical conditions.",
    "Potential first-pass metabolism of the query is inferred from analogues rather than measured directly."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

